CustomField.formula:
IF(
  /*If Account is IMGA, stores IM_Industry__c*/
 ISPICKVAL(IM_Hierarchy_Level__c, 'IM Group (IMGA)'), Text(IM_Industry__c),
IF(
  /*If Account is Country Parent, stores IMGA Account's IM_Industry__c by traversing one level up the hierarchy*/
 ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'),  Text(Parent.IM_Industry__c) ,
IF(
  /*If Account is Sales site, stores CP Account's IM_Industry__c by traversing one level up the hierarchy*/
AND(ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'),NOT(ISBLANK(Parent.ParentId)),(ISPICKVAL(Parent.IM_Hierarchy_Level__c,'Country Parent')),(Parent.Industry_Override__c = True )),    
Text(Parent.IM_Industry__c), Text(Parent.Parent.IM_Industry__c))))
